function longestLoop(next: number[]): number {
  const n = next.length;
  const indeg = new Array(n).fill(0);
  for (const v of next) if (v !== -1) indeg[v]++;
  const queue: number[] = [];
  for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);
  const gone = new Array(n).fill(false);
  for (let h = 0; h < queue.length; h++) {
    const u = queue[h];
    gone[u] = true;
    const v = next[u];
    if (v !== -1 && --indeg[v] === 0) queue.push(v);
  }
  let best = -1;
  for (let i = 0; i < n; i++) {
    if (gone[i]) continue;
    let len = 0, u = i;
    do { gone[u] = true; u = next[u]; len++; } while (u !== i);
    best = Math.max(best, len);
  }
  return best;
}

